import java.util.HashSet

class BadSetElement {
    fun bad(elem: BadElement): Boolean {
        val mySet: HashSet<BadElement> = HashSet()
        mySet.add(elem)
        return mySet.contains(elem)
    }
}

class BadElement

import java.util.HashSet

class GoodStringSet {
    fun good(elem: String): Boolean {
        val mySet: Set<String> = HashSet()
        return mySet.contains(elem)
    }
}

import java.util.Comparator
import java.util.TreeSet

class GoodTreeSet {
    fun good(elem: MyClass): Boolean {
        val comparator = Comparator<MyClass> { left, right -> left.id.compareTo(right.id) }
        val mySet: TreeSet<MyClass> = TreeSet(comparator)
        return mySet.contains(elem)
    }
}

class MyClass(val id: String)

class GoodSetOf {
    fun good(elem: String): Boolean {
        val mySet: Set<String> = setOf()
        return mySet.contains(elem)
    }
}
